<script setup lang="ts">
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, reactive, ref } from 'vue';
import ErpLayout from '@/Layouts/ErpLayout.vue';
import type { ReconciliationDetail, StatementLine } from '@/Types/treasury';

defineOptions({ layout: ErpLayout });
const props = defineProps<{ reconciliation: ReconciliationDetail }>();
const processing = ref<string | null>(null);
const selections = reactive<Record<number, { journal_entry_line_id: number | null; matched_amount: string }>>({});
for (const line of props.reconciliation.statement_lines) {
    const remaining = Math.max(Math.abs(Number(line.signed_amount)) - Number(line.matched_amount), 0);
    selections[line.id] = { journal_entry_line_id: null, matched_amount: remaining.toFixed(6) };
}
const matchesByLine = computed(() => {
    const result: Record<number, typeof props.reconciliation.matches> = {};
    for (const match of props.reconciliation.matches) (result[match.statement_line_id] ??= []).push(match);
    return result;
});
const money = (v: string | null): string => v === null ? '—' : new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 6 }).format(Number(v));
const action = (name: string, confirmation: string, payload: Record<string, string> = {}): void => {
    if (!window.confirm(confirmation)) return;
    processing.value = name;
    router.post(route(`bank-reconciliations.${name}`, props.reconciliation.id), payload, { preserveScroll: true, onFinish: () => { processing.value = null; } });
};
const manualMatch = (line: StatementLine): void => {
    const selection = selections[line.id];
    if (!selection || selection.journal_entry_line_id === null || Number(selection.matched_amount) <= 0) return;
    router.post(route('bank-reconciliations.manual-match', props.reconciliation.id), { bank_statement_line_id: line.id, journal_entry_line_id: selection.journal_entry_line_id, matched_amount: selection.matched_amount }, { preserveScroll: true });
};
const unmatch = (id: number): void => { if (window.confirm('Remove this bank reconciliation match?')) router.delete(route('bank-reconciliations.unmatch', [props.reconciliation.id, id]), { preserveScroll: true }); };
const ignore = (line: StatementLine): void => { const reason = window.prompt('Reason for ignoring this bank statement line:')?.trim() ?? ''; if (reason) router.post(route('bank-reconciliations.ignore', [props.reconciliation.id, line.id]), { reason }, { preserveScroll: true }); };
const unignore = (line: StatementLine): void => router.post(route('bank-reconciliations.unignore', [props.reconciliation.id, line.id]), {}, { preserveScroll: true });
const reverse = (): void => { const reason = window.prompt('Reason for reversing this reconciliation:')?.trim() ?? ''; if (reason) action('reverse', 'Reverse this completed reconciliation?', { reason }); };
const deleteSession = (): void => { if (window.confirm('Delete this draft reconciliation?')) router.delete(route('bank-reconciliations.destroy', props.reconciliation.id)); };
</script>

<template><Head :title="reconciliation.reconciliation_number ?? `Bank Reconciliation #${reconciliation.id}`"/><div class="space-y-6"><div class="flex flex-col gap-4 xl:flex-row xl:items-start xl:justify-between"><div><Link :href="route('bank-reconciliations.index')" class="text-sm text-brand-600">Bank Reconciliations</Link><div class="mt-2 flex items-center gap-3"><h1 class="text-2xl font-semibold">{{reconciliation.reconciliation_number??`Session #${reconciliation.id}`}}</h1><span class="rounded-full bg-gray-100 px-2.5 py-1 text-xs dark:bg-gray-800">{{reconciliation.status_label}}</span></div><p class="mt-1 text-sm text-gray-500">{{reconciliation.bank_account?.code}} — {{reconciliation.bank_account?.name}} · {{reconciliation.statement_start_date}} to {{reconciliation.statement_end_date}}</p></div><div class="flex flex-wrap gap-2"><a :href="route('bank-reconciliations.print',reconciliation.id)" target="_blank" class="rounded-lg border px-4 py-2.5 text-sm dark:border-gray-700">Print</a><button v-if="reconciliation.can.match" class="rounded-lg border px-4 py-2.5 text-sm dark:border-gray-700" :disabled="processing!==null" @click="action('refresh','Refresh reconciliation balances?')">Refresh</button><button v-if="reconciliation.can.match" class="rounded-lg bg-brand-500 px-4 py-2.5 text-sm text-white" :disabled="processing!==null" @click="action('automatic-match','Run automatic exact matching?')">Automatic Match</button><button v-if="reconciliation.can.complete" class="rounded-lg bg-success-600 px-4 py-2.5 text-sm text-white" @click="action('complete','Complete and lock this reconciliation?')">Complete</button><button v-if="reconciliation.can.reverse" class="rounded-lg bg-error-600 px-4 py-2.5 text-sm text-white" @click="reverse">Reverse</button><button v-if="reconciliation.can.match" class="rounded-lg border border-error-300 px-4 py-2.5 text-sm text-error-600" @click="deleteSession">Delete</button></div></div>
<div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><div v-for="x in [['Statement Closing',reconciliation.statement_closing_balance],['Book Closing',reconciliation.book_closing_balance],['Outstanding Deposits',reconciliation.outstanding_deposits],['Outstanding Payments',reconciliation.outstanding_payments],['Difference',reconciliation.difference_amount]]" :key="String(x[0])" class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><p class="text-xs uppercase text-gray-500">{{x[0]}}</p><p class="mt-2 text-lg font-semibold" :class="x[0]==='Difference'&&Number(x[1])!==0?'text-error-600':''">{{money(String(x[1]))}}</p></div></div>
<div v-if="reconciliation.status==='reversed'" class="rounded-xl border border-error-200 bg-error-50 p-4 text-sm text-error-700"><b>Reversed:</b> {{reconciliation.reversal_reason}}</div>
<div class="overflow-hidden rounded-2xl border bg-white dark:border-gray-800 dark:bg-gray-900"><div class="border-b p-5 dark:border-gray-800"><h2 class="text-lg font-semibold">Statement Matching Workbench</h2><p class="mt-1 text-sm text-gray-500">Positive statement amounts are deposits; negative amounts are payments. Partial matching is supported.</p></div><div class="overflow-x-auto"><table class="min-w-[1450px] w-full"><thead class="bg-gray-50 dark:bg-white/[.03]"><tr><th class="p-3 text-left text-xs uppercase text-gray-500">Statement Line</th><th class="p-3 text-left text-xs uppercase text-gray-500">Description</th><th class="p-3 text-right text-xs uppercase text-gray-500">Amount</th><th class="p-3 text-right text-xs uppercase text-gray-500">Matched</th><th class="p-3 text-left text-xs uppercase text-gray-500">Existing Matches</th><th class="p-3 text-left text-xs uppercase text-gray-500">Manual Match</th><th class="p-3 text-right text-xs uppercase text-gray-500">Exception</th></tr></thead><tbody class="divide-y dark:divide-gray-800"><tr v-for="line in reconciliation.statement_lines" :key="line.id"><td class="p-3 text-sm"><b>#{{line.line_number}} · {{line.transaction_date}}</b><p class="text-xs text-gray-500">{{line.bank_reference??'No reference'}} · {{line.status}}</p></td><td class="p-3 text-sm">{{line.description??'—'}}</td><td class="p-3 text-right font-semibold" :class="Number(line.signed_amount)>=0?'text-success-600':'text-error-600'">{{money(line.signed_amount)}}</td><td class="p-3 text-right text-sm">{{money(line.matched_amount)}}</td><td class="p-3"><div class="space-y-2"><div v-for="match in matchesByLine[line.id]??[]" :key="match.id" class="rounded border p-2 text-xs dark:border-gray-700"><div class="flex justify-between gap-3"><span>{{match.journal?.journal_number??'Journal'}} · {{money(match.matched_amount)}}</span><button v-if="reconciliation.can.match" class="text-error-600" @click="unmatch(match.id)">Remove</button></div><p class="mt-1 text-gray-500">{{match.journal?.source_document_number??match.journal?.description??'—'}}</p></div><span v-if="!(matchesByLine[line.id]?.length)" class="text-xs text-gray-400">No match</span></div></td><td class="p-3"><div v-if="reconciliation.can.match&&line.status!=='ignored'" class="flex min-w-[450px] gap-2"><select v-model="selections[line.id].journal_entry_line_id" class="h-10 min-w-0 flex-1 rounded border px-2 text-xs dark:border-gray-700"><option :value="null">Select posted bank journal line</option><option v-for="j in reconciliation.available_journal_lines" :key="j.id" :value="j.id">{{j.posting_date}} · {{j.journal_number}} · {{j.source_document_number??j.description}} · available {{j.available_amount}}</option></select><input v-model="selections[line.id].matched_amount" type="number" min="0.000001" step="0.000001" class="h-10 w-32 rounded border px-2 text-right text-xs dark:border-gray-700"/><button class="rounded bg-brand-500 px-3 text-xs text-white" @click="manualMatch(line)">Match</button></div></td><td class="p-3 text-right"><div v-if="reconciliation.can.match" class="flex justify-end gap-2"><Link v-if="line.status!=='matched'&&line.status!=='ignored'" :href="route('treasury-adjustments.create',{bank_statement_line_id:line.id})" class="text-xs text-brand-600">Create adjustment</Link><button v-if="line.status!=='ignored'" class="text-xs text-warning-600" @click="ignore(line)">Ignore</button><button v-else class="text-xs text-brand-600" @click="unignore(line)">Restore</button></div><span v-if="line.ignore_reason" class="mt-1 block text-xs text-gray-500">{{line.ignore_reason}}</span></td></tr></tbody></table></div></div>
<div class="grid gap-6 lg:grid-cols-2"><div class="rounded-2xl border bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><h2 class="text-lg font-semibold">Adjusted Bank Balance</h2><dl class="mt-5 grid grid-cols-2 gap-3 text-sm"><dt class="text-gray-500">Statement closing</dt><dd class="text-right">{{money(reconciliation.statement_closing_balance)}}</dd><dt class="text-gray-500">Add outstanding deposits</dt><dd class="text-right">{{money(reconciliation.outstanding_deposits)}}</dd><dt class="text-gray-500">Less outstanding payments</dt><dd class="text-right">{{money(reconciliation.outstanding_payments)}}</dd><dt class="border-t pt-3 font-semibold">Adjusted bank</dt><dd class="border-t pt-3 text-right font-semibold">{{money(reconciliation.adjusted_bank_balance)}}</dd></dl></div><div class="rounded-2xl border bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><h2 class="text-lg font-semibold">Session Information</h2><dl class="mt-5 grid grid-cols-2 gap-3 text-sm"><dt class="text-gray-500">Statement</dt><dd>{{reconciliation.statement?.reference}}</dd><dt class="text-gray-500">Created by</dt><dd>{{reconciliation.created_by?.name??'—'}}</dd><dt class="text-gray-500">Completed by</dt><dd>{{reconciliation.completed_by?.name??'—'}}</dd><dt class="text-gray-500">Notes</dt><dd class="whitespace-pre-line">{{reconciliation.notes??'—'}}</dd></dl></div></div></div></template>
